BEGIN;
SELECT no_plan();
SELECT has_column('public', 'executions', 'title', 'Execução tem título');
SELECT has_column('public', 'executions', 'plan', 'Execução tem plano');
SELECT has_column('public', 'executions', 'reserved_credits', 'Execução tem créditos reservados');
SELECT has_function('public', 'execution_control', ARRAY['uuid','uuid','text'], 'Controle de execução existe');
SELECT is((SELECT count(*)::integer FROM public.executions WHERE workspace_id = 'a0000000-0000-0000-0000-000000000001'), 8, 'Seed traz as oito execuções');
INSERT INTO public.credit_wallets(workspace_id, reserved_balance) VALUES ('a0000000-0000-0000-0000-000000000001',100)
ON CONFLICT(workspace_id) DO UPDATE SET reserved_balance=public.credit_wallets.reserved_balance+100;
INSERT INTO public.credit_transactions(workspace_id,execution_id,type,amount,wallet_type,description)
VALUES ('a0000000-0000-0000-0000-000000000001','ec000000-0000-0000-0000-000000001035','reserve',100,'both','Reserva do teste de cancelamento');
SET LOCAL ROLE authenticated;
SET LOCAL "request.jwt.claims" = '{"sub":"e0000000-0000-0000-0000-000000000004","role":"authenticated"}';
SELECT is((SELECT count(*)::integer FROM public.executions), 0, 'BDR não lê execuções');
SELECT throws_ok($$ SELECT public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000002','pause') $$, '42501', NULL, 'BDR não se passa pelo estrategista');
SET LOCAL "request.jwt.claims" = '{"sub":"e0000000-0000-0000-0000-000000000003","role":"authenticated"}';
SELECT is((SELECT count(*)::integer FROM public.executions), 8, 'C-level lê execuções');
SELECT throws_ok($$ SELECT public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000003','pause') $$, '42501', NULL, 'C-level não controla execução');
SELECT throws_ok($$ SELECT * FROM public.execution_costs('a0000000-0000-0000-0000-000000000001') $$, '42501', NULL, 'C-level não lê custo real pela API');
SET LOCAL "request.jwt.claims" = '{"sub":"e0000000-0000-0000-0000-000000000002","role":"authenticated"}';
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000002','pause')->>'status','paused','Estrategista pausa');
SELECT is((SELECT status FROM public.executions WHERE id='ec000000-0000-0000-0000-000000001042'),'paused','Pausa persiste');
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000002','resume')->>'status','queued','Retomada volta à fila do worker');
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000002','cancel')->>'status','cancelled','Cancelamento persiste');
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000002','pause')->>'success','false','Não pausa execução encerrada');
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001038','d0000000-0000-0000-0000-000000000002','repeat')->>'success','true','Repetir cria nova execução');
SELECT is((SELECT count(*)::integer FROM public.executions),9,'Repetição preserva original');
SELECT is((SELECT status FROM public.executions WHERE id='ec000000-0000-0000-0000-000000001038'),'failed','Original continua com falha');
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001035','d0000000-0000-0000-0000-000000000002','cancel')->>'success','true','Cancela execução com reserva');
SELECT is((SELECT amount FROM public.credit_transactions WHERE idempotency_key='cancel:ec000000-0000-0000-0000-000000001035'),100,'Cancelamento libera reserva no ledger');
SELECT is(public.execution_control('ec000000-0000-0000-0000-000000001035','d0000000-0000-0000-0000-000000000002','cancel')->>'success','false','Segundo cancelamento não libera de novo');
SET LOCAL "request.jwt.claims" = '{"sub":"e0000000-0000-0000-0000-000000000007","role":"authenticated"}';
SELECT is((SELECT count(*)::integer FROM public.executions),0,'Outro workspace não lê execuções da Evolut');
SELECT throws_ok($$ SELECT public.execution_control('ec000000-0000-0000-0000-000000001042','d0000000-0000-0000-0000-000000000009','cancel') $$,'42501',NULL,'Outro workspace não controla execução');
SET LOCAL "request.jwt.claims" = '{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}';
SELECT is((SELECT cost_usd FROM public.execution_costs('a0000000-0000-0000-0000-000000000001') WHERE execution_id='ec000000-0000-0000-0000-000000001042'),41.20::numeric,'Superadmin lê custo');
RESET ROLE;
SELECT ok(NOT has_function_privilege('anon','public.execution_control(uuid,uuid,text)','EXECUTE'),'anon não controla');
SELECT ok(NOT has_function_privilege('anon','public.execution_costs(uuid)','EXECUTE'),'anon não lê custos');
SELECT * FROM finish();
ROLLBACK;